"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79890"],{9029(e){e.exports=JSON.parse('{"id":"V4-076","slug":"remuneration-committee","term":"Remuneration Committee","also_known_as":[],"difficulty":"Intermediate","definition":"A remuneration committee is a committee of a company\u2019s board of directors, usually made up of independent directors, responsible for setting the pay policy and individual pay packages for senior executives.","explanation":["Executives should not decide their own pay. The remuneration committee, called the compensation committee in the United States, designs and approves executive pay, including salaries, bonuses, long-term incentive plans, pensions and benefits.","The committee aims to attract and retain talented leaders while linking pay to performance and long-term shareholder value. It typically sets performance targets for bonuses and share awards, considers pay levels at comparable companies and wider employee pay, and decides whether targets have been met.","For example, a remuneration committee might decide that a chief executive\u2019s annual bonus depends on meeting profit and safety targets, and that long-term share awards vest only if the company\u2019s shareholder returns beat those of its peers over three years.","Executive pay is often controversial, and committees face scrutiny from shareholders, the media and employees. Many countries require companies to publish a detailed remuneration report and give shareholders a vote on pay, known as say on pay. Committees often use independent pay consultants to support their decisions."],"note":"","total":1725,"prev":{"slug":"remortgage","term":"Remortgage"},"next":{"slug":"rent","term":"Rent"}}')}}]);